var debug = require('debug')('mendel:tree-hash-walker');
var util = require('util');
var xtend = require('xtend');

var deserialize = require('./tree-deserialiser');
var MendelWalker = require('./tree-walker');

util.inherits(MendelHashWalker, MendelWalker);
module.exports = MendelHashWalker;

function MendelHashWalker(inputHash) {
    debug('init MendelHashWalker');
    if (!(this instanceof MendelHashWalker)) {
        return new MendelHashWalker(inputHash);
    }
    MendelWalker.call(this);

    var result = deserialize(inputHash);
    this.error = result.error;
    this.decoded = result.decoded;

    this.inputHash = inputHash;
    this.pathCount = 0;
}

MendelHashWalker.prototype._resolveBranch = function (module) {
    if (this.error) return {};

    var nextPath;
    var resolved;
    if (this.pathCount >= this.decoded.branches.length) {
        this._error('Tree has more paths than hash');
    } else {
        nextPath = this.decoded.branches[this.pathCount];
        resolved = module.data[nextPath];
        if (!resolved) {
            this._error('Hash branch not found in tree');
        }
    }
    this.pathCount++;
    return {
        index: nextPath,
        resolved: resolved || {},
    };
};

MendelHashWalker.prototype._error = function (msg) {
    this.error = this.error || new Error(msg);
    this.error.code = 'TRVRSL';
    debug(this.error);
};

MendelHashWalker.prototype.found = function () {
    this._result = MendelWalker.prototype.found.call(this);

    if (!this.error && this._result.hash !== this.inputHash) {
        var error = new Error('Tree Hash Mismatch');
        error.code = 'HASHMISS';
        this.error = error;
    }

    return xtend(this._result, {
        error: this.error,
    });
};

/* Copyright 2015, Yahoo Inc.
   Designed by Irae Carvalho
   Copyrights licensed under the MIT License.
   See the accompanying LICENSE file for terms. */

var debug = require('debug')('mendel:tree-variation-walker');
var util = require('util');
var xtend = require('xtend');

var MendelWalker = require('./tree-walker');

util.inherits(MendelVariationWalker, MendelWalker);
module.exports = MendelVariationWalker;

function MendelVariationWalker(_lookupChains, _base, _hash) {
    debug('init MendelVariationWalker');
    if (!(this instanceof MendelVariationWalker)) {
        return new MendelVariationWalker(_lookupChains, _base, _hash);
    }
    MendelWalker.call(this);

    this._lookupChains = _lookupChains;
    this._base = _base;
    this.conflicts = 0;
    this.conflictList = {};
}

MendelVariationWalker.prototype._resolveBranch = function (module) {
    var fileId = module.id;
    var resolved;
    var foundIn = 0;
    var pathIndex = 0;
    for (var i = 0; i < this._lookupChains.length; i++) {
        for (var j = 0; j < this._lookupChains[i].length; j++) {
            var index = module.variations.indexOf(this._lookupChains[i][j]);
            if (-1 !== index) {
                if (!foundIn) {
                    // keep first match, priority by .mendelrc entry order
                    resolved = module.data[index];
                    pathIndex = index;
                }
                if (!foundIn || this._lookupChains[i][j] !== this._base) {
                    // config.base don't cont as conflict
                    foundIn++;
                }
                break;
            }
        }
    }
    if (foundIn > 1) {
        this.conflicts++;
        this.conflictList[fileId] = true;
    }
    return {
        index: pathIndex,
        resolved: resolved,
    };
};

MendelVariationWalker.prototype.found = function () {
    return xtend(MendelWalker.prototype.found.call(this), {
        conflicts: this.conflicts,
        conflictList: this.conflictList,
    });
};

